import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import { Polymorphic } from "@kobalte/core/polymorphic";
import type { ComponentProps, ValidComponent } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import IconArrowRight01 from "~icons/hugeicons/arrow-right-01";
import IconMoreHorizontal from "~icons/hugeicons/more-horizontal";
import type { Component } from "solid-js";

import { children, omit, Show } from "solid-js";

const Breadcrumb: Component<ComponentProps<"nav">> = (props) => {
  const others = omit(props, "class");
  return (
    <nav
      aria-label="breadcrumb"
      data-slot="breadcrumb"
      class={cn(props.class)}
      {...others}
    />
  );
};

const BreadcrumbList: Component<ComponentProps<"ol">> = (props) => {
  const others = omit(props, "class");
  return (
    <ol
      data-slot="breadcrumb-list"
      class={cn(
        "text-muted-foreground gap-1.5 text-xs uppercase tracking-wide sm:gap-2.5 wrap-break-word flex flex-wrap items-center",
        props.class,
      )}
      {...others}
    />
  );
};

const BreadcrumbItem: Component<ComponentProps<"li">> = (props) => {
  const others = omit(props, "class");
  return (
    <li
      data-slot="breadcrumb-item"
      class={cn("gap-1.5 inline-flex items-center", props.class)}
      {...others}
    />
  );
};

type BreadcrumbLinkProps<T extends ValidComponent = "a"> =
  & ComponentProps<"a">
  & { class?: string | undefined };

const BreadcrumbLink = <T extends ValidComponent = "a">(
  props: PolymorphicProps<T, BreadcrumbLinkProps<T>>,
) => {
  const local = props as BreadcrumbLinkProps;
  const others = omit(local, "class");
  return (
    <Polymorphic
      as="a"
      data-slot="breadcrumb-link"
      class={cn("hover:text-foreground transition-colors", local.class)}
      {...others}
    />
  );
};

const BreadcrumbPage: Component<ComponentProps<"span">> = (props) => {
  const others = omit(props, "class");
  return (
    <span
      data-slot="breadcrumb-page"
      role="link"
      aria-disabled="true"
      aria-current="page"
      class={cn("text-foreground font-normal", props.class)}
      {...others}
    />
  );
};

const BreadcrumbSeparator: Component<ComponentProps<"li">> = (props) => {
  const others = omit(props, "class", "children");

  const resolvedChildren = children(() => props.children);
  const hasChildren = () => resolvedChildren.toArray().length !== 0;

  return (
    <li
      data-slot="breadcrumb-separator"
      role="presentation"
      aria-hidden="true"
      class={cn("[&>svg]:size-3.5", props.class)}
      {...others}
    >
      <Show when={!hasChildren()} fallback={resolvedChildren()}>
        <IconArrowRight01
          class="cn-rtl-flip"
        />
      </Show>
    </li>
  );
};

const BreadcrumbEllipsis: Component<ComponentProps<"span">> = (props) => {
  const others = omit(props, "class");
  return (
    <span
      data-slot="breadcrumb-ellipsis"
      role="presentation"
      aria-hidden="true"
      class={cn(
        "size-5 [&>svg]:size-4 flex items-center justify-center",
        props.class,
      )}
      {...others}
    >
      <IconMoreHorizontal
      />
      <span class="sr-only">More</span>
    </span>
  );
};

export {
  Breadcrumb,
  BreadcrumbEllipsis,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
};
